def build_fruits():
    seen = set()
    items = []
    for row in FRUITS_DATA:
        add_entry(items, seen, row[0], row[1], row[2], row[3])
    print_summary('Fruits', items)
    return items

if __name__ == '__main__':
    build_fruits()
